package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TypeBindings.toString()
 */
public class TypeBindings_toString_TriageGen2Test {





    @Test
    public void testToString_MultipleTypes() {
        // Test the branch: i > 0 (comma appended)
        JavaType type1 = mock(JavaType.class);
        JavaType type2 = mock(JavaType.class);
        JavaType type3 = mock(JavaType.class);

        when(type1.getGenericSignature()).thenReturn("Integer");
        when(type2.getGenericSignature()).thenReturn("Boolean");
        when(type3.getGenericSignature()).thenReturn("Double");

        TypeBindings bindings = TypeBindings.create(Object.class, new JavaType[]{type1, type2, type3});

        // Expected format: <sig1,sig2,sig3>
        assertEquals("<Integer,Boolean,Double>", bindings.toString());
    }


}

package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TypeBindings.toString()
 */
public class TypeBindings_toString_TriageGen2Test {







    @Test
    public void testToString_WithComplexSignatures() {
        // Test with signatures containing special characters to ensure StringBuilder handles them
        JavaType type1 = mock(JavaType.class);
        JavaType type2 = mock(JavaType.class);

        when(type1.getGenericSignature()).thenReturn("List<String>");
        when(type2.getGenericSignature()).thenReturn("Map<String, Integer>");

        TypeBindings bindings = TypeBindings.create(Object.class, type1, type2);

        assertEquals("<List<String>,Map<String, Integer>>", bindings.toString());
    }
}
